#!/usr/bin/env python3
"""Derive bazel/sm.bazelrc from arch_config/sm_matrix.bzl.

Usage:
    python3 deps/gen_sm_bazelrc.py          # write bazel/sm.bazelrc
    scripts/rtpcli deps check --all         # verify generated output and all dependency gates

The only hand-written surface is sm_matrix.bzl; sm.bazelrc is generated, hand-editing forbidden.
"""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))


def _find_root(start):
    """Walk up to the directory containing .git (a directory in the main repo, a file in the submodule)."""
    d = start
    while True:
        if os.path.exists(os.path.join(d, ".git")):
            return d
        parent = os.path.dirname(d)
        if parent == d:
            sys.exit(
                f"FAIL: no .git found walking up from {start}, cannot locate the repo root"
            )
        d = parent


ROOT = _find_root(HERE)
MATRIX_PATH = os.path.join(ROOT, "arch_config", "sm_matrix.bzl")
OUT_PATH = os.path.join(ROOT, "bazel", "sm.bazelrc")

HEADER = """# GENERATED by deps/gen_sm_bazelrc.py from arch_config/sm_matrix.bzl -- do not edit by hand
# Regenerate with `scripts/rtpcli deps sync --all`; verify with `scripts/rtpcli deps check --all`.
# The single source of truth for SM lists is arch_config/sm_matrix.bzl.
"""


def load_matrix():
    ns = {}
    with open(MATRIX_PATH, encoding="utf-8") as f:
        code = compile(f.read(), MATRIX_PATH, "exec")
    exec(code, ns)  # sm_matrix.bzl contains only dict/str literal assignments
    for name in ("CUDA_SM_MATRIX", "ROCM_ARCH_MATRIX", "SM_KNOBS"):
        if name not in ns:
            sys.exit(f"FAIL: {MATRIX_PATH} is missing {name}")
    return ns


def validate(ns):
    """Pin the release red line: CUDA values must be x.y only (keep PTX), no sm_ prefix."""
    cap_re = re.compile(r"^\d+\.\d+$")
    gfx_re = re.compile(r"^gfx\d+$")
    for cfg, val in ns["CUDA_SM_MATRIX"].items():
        for cap in val.split(","):
            if not cap_re.match(cap.strip()):
                sys.exit(
                    f"FAIL: {cap.strip()!r} of {cfg} is not in x.y form; "
                    "release configs forbid the sm_ prefix (PTX red line, see the sm_matrix.bzl docstring)"
                )
    for cfg, val in ns["ROCM_ARCH_MATRIX"].items():
        for arch in val.split(","):
            if not gfx_re.match(arch.strip()):
                sys.exit(f"FAIL: {arch.strip()!r} of {cfg} is not in gfxNNN form")
    for cfg, val in ns["SM_KNOBS"].items():
        for cap in val.split(","):
            if not cap_re.match(cap.strip()):
                sys.exit(f"FAIL: {cap.strip()!r} of knob {cfg} is not in x.y form")


def render(ns):
    lines = [HEADER]
    for cfg, val in ns["CUDA_SM_MATRIX"].items():
        for kind in ("action_env", "host_action_env", "repo_env"):
            lines.append(f'build:{cfg} --{kind} TF_CUDA_COMPUTE_CAPABILITIES="{val}"')
        lines.append("")
    for cfg, val in ns["SM_KNOBS"].items():
        for kind in ("action_env", "host_action_env", "repo_env"):
            lines.append(f'build:{cfg} --{kind} TF_CUDA_COMPUTE_CAPABILITIES="{val}"')
        lines.append("")
    for cfg, val in ns["ROCM_ARCH_MATRIX"].items():
        lines.append(f'build:{cfg} --action_env GPU_ARCHS="{val}"')
        lines.append(f'build:{cfg} --repo_env GPU_ARCHS="{val}"')
        lines.append("")
    return "\n".join(lines).rstrip("\n") + "\n"


def main():
    check = "--check" in sys.argv[1:]
    ns = load_matrix()
    validate(ns)
    want = render(ns)
    have = ""
    if os.path.exists(OUT_PATH):
        with open(OUT_PATH, encoding="utf-8") as f:
            have = f.read()
    if check:
        if have != want:
            sys.exit(
                f"FAIL: {os.path.relpath(OUT_PATH, ROOT)} is not the latest derivation of arch_config/sm_matrix.bzl; "
                "run python3 deps/gen_sm_bazelrc.py"
            )
        print(
            f"OK: {os.path.relpath(OUT_PATH, ROOT)} matches the sm_matrix.bzl derivation"
        )
        return
    if have == want:
        print(
            f"unchanged: {os.path.relpath(OUT_PATH, ROOT)} is already the latest derivation"
        )
        return
    with open(OUT_PATH, "w", encoding="utf-8") as f:
        f.write(want)
    print(f"generated: {os.path.relpath(OUT_PATH, ROOT)}")


if __name__ == "__main__":
    main()
